import math

def sigma(n):
    """Calculates the sum of divisors function sigma(n)."""
    if n <= 0:
        return 0
    result = 1
    p = 2
    temp_n = n
    while p * p <= temp_n:
        if temp_n % p == 0:
            exponent = 0
            while temp_n % p == 0:
                exponent += 1
                temp_n //= p
            # Formula for sum of divisors of p^e: (p^(e+1) - 1) / (p - 1)
            result *= (p**(exponent + 1) - 1) // (p - 1)
        p += 1
    if temp_n > 1:
        # The remaining temp_n is a prime factor
        result *= (temp_n**2 - 1) // (temp_n - 1) # which is temp_n + 1
    return result

def is_square(n):
    """Checks if n is a perfect square."""
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def find_candidates(start_m, end_m):
    candidates = []
    for m in range(start_m, end_m + 1):
        s_m = sigma(m)
        if is_square(s_m):
            candidates.append((m, s_m))
    return candidates

