from collections import deque

def get_divisors(m):
    divs = set()
    for i in range(1, int(math.sqrt(m)) + 1):
        if m % i == 0:
            divs.add(i)
            divs.add(m // i)
    return sorted(list(divs))

def is_perfect_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def find_valid_permutation(m, initial_a1=1):
    divisors = get_divisors(m)
    n = len(divisors)

    # Check if the required starting divisor is available
    if initial_a1 not in divisors:
        return False

    # Check the final condition (Sigma(m) must be a square)
    sigma_m = sum(divisors)
    if not is_perfect_square(sigma_m):
        return False

    # A recursive backtracking approach is suitable here

    # Initial checks
    if not is_perfect_square(initial_a1):
        return False

    start_sum = initial_a1
    remaining_divisors = [d for d in divisors if d != initial_a1]

    # DFS function: (current_sum, remaining_divisors_set)
    def dfs(current_sum, remaining):
        if not remaining:
            # If we used all divisors, the final sum must equal sigma_m (which we pre-checked)
            return current_sum == sigma_m

        for i in range(len(remaining)):
            a_i = remaining[i]
            next_sum = current_sum + a_i

            if is_perfect_square(next_sum):
                # Found a valid step, recurse
                next_remaining = remaining[:i] + remaining[i+1:]
                if dfs(next_sum, next_remaining):
                    return True
        return False

    # Start the DFS search
    return dfs(start_sum, remaining_divisors)

